<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, APIError, csrfToken, type AnyConnectAssetState, type AnyConnectUser, type AnyConnectUserInput, type AnyConnectUserTraffic, type Audit, type Backup, type ClientConfig, type Node, type NodeInput, type NodeLogs, type NodeType, type ProjectTraffic, type SystemSettings, type Traffic, type UpdateComponent, type UpdateStatus } from './api'
import { copyToClipboard } from './clipboard'
import { applyTheme, getStoredTheme, nextTheme, type Theme } from './theme'

type Phase='loading'|'login'|'change'|'app'
type Page='dashboard'|'nodes'|'traffic'|'updates'|'audit'|'settings'
const phase=ref<Phase>('loading'), page=ref<Page>('dashboard'), busy=ref(false), error=ref(''), notice=ref('')
const theme=ref<Theme>(getStoredTheme())
const password=ref(''), newPassword=ref(''), confirmPassword=ref('')
const nodes=ref<Node[]>([]), traffic=ref<Traffic[]>([]), backups=ref<Backup[]>([]), audits=ref<Audit[]>([])
const projectTraffic=ref<ProjectTraffic>({period:'',uploadBytes:0,downloadBytes:0,quotaBytes:0,resetDay:1,paused:false,pausedByQuota:false,updatedAt:''})
const systemSettings=ref<SystemSettings>({logMaxMB:10,logEnabled:true,updatedAt:''}), logMaxMB=ref(10), logEnabled=ref(true)
const update=ref<UpdateStatus|null>(null), selectedType=ref<NodeType>('snell'), showEditor=ref(false), editing=ref<Node|null>(null), showDetails=ref(false), detailTitle=ref(''), detailText=ref(''), detailConfig=ref<ClientConfig|null>(null), detailNode=ref<Node|null>(null)
const copiedKey=ref(''), showTrafficEditor=ref(false), trafficEditing=ref<Traffic|null>(null), trafficQuotaGiB=ref(0), trafficResetDay=ref(1)
const showProjectTrafficEditor=ref(false), projectQuotaGiB=ref(0), projectResetDay=ref(1)
const auditMode=ref<'runtime'|'audit'>('runtime'), logNodeId=ref(''), nodeLogs=ref<NodeLogs>({lines:[],totalBytes:0,updatedAt:''}), logTail=ref(300), logBusy=ref(false)
const uploadComponent=ref('snell'), uploadVersion=ref(''), uploadFormat=ref('zip'), uploadSHA256=ref(''), uploadFile=ref<File|null>(null), uploadConfirmed=ref(false), uploadFileInput=ref<HTMLInputElement|null>(null)
const syncFile=ref<File|null>(null), syncFileInput=ref<HTMLInputElement|null>(null), syncReplaceUsers=ref(false), showSync=ref(false)
const showAnyConnect=ref(false), anyConnectNode=ref<Node|null>(null), anyConnectUsers=ref<AnyConnectUser[]>([]), anyConnectUserTraffic=ref<Record<string,AnyConnectUserTraffic>>({}), anyConnectAssets=ref<AnyConnectAssetState|null>(null), showAnyConnectUserEditor=ref(false), editingAnyConnectUser=ref<AnyConnectUser|null>(null), anyConnectUserForm=ref<AnyConnectUserInput>({username:'',password:'',routeGroup:'cn',enabled:true})
const showAnyConnectTrafficEditor=ref(false), anyConnectTrafficEditing=ref<AnyConnectUser|null>(null), anyConnectTrafficQuotaGiB=ref(0), anyConnectTrafficResetDay=ref(1)
const form=ref<NodeInput>(blank('snell'))
const nav:Array<{id:Page;label:string;icon:string}>=[{id:'dashboard',label:'仪表盘',icon:'⌁'},{id:'nodes',label:'节点管理',icon:'◆'},{id:'traffic',label:'流量管理',icon:'↕'},{id:'updates',label:'更新与备份',icon:'↻'},{id:'audit',label:'日志与审计',icon:'≡'},{id:'settings',label:'系统设置',icon:'⚙'}]
const filteredNodes=computed(()=>nodes.value.filter(node=>node.type===selectedType.value))
const anyConnectNodes=computed(()=>nodes.value.filter(node=>node.type==='anyconnect'))
const anyConnectUsersWithTraffic=computed(()=>anyConnectUsers.value.map(user=>({user,traffic:anyConnectUserTraffic.value[user.id]??{userId:user.id,period:'',uploadBytes:0,downloadBytes:0,quotaBytes:0,resetDay:1,paused:false,pausedByQuota:false,updatedAt:''}})))
const anyConnectUsersByNode=computed(()=>Object.fromEntries(anyConnectNodes.value.map(node=>[node.id,anyConnectUsersWithTraffic.value.filter(entry=>entry.user.nodeId===node.id)])))
const counts=computed(()=>({snell:nodes.value.filter(n=>n.type==='snell').length,ss2022:nodes.value.filter(n=>n.type==='ss2022').length,shadowtls:nodes.value.filter(n=>n.type==='shadowtls').length,anyconnect:nodes.value.filter(n=>n.type==='anyconnect').length}))
const publicTraffic=computed(()=>traffic.value.filter(item=>{const node=nodes.value.find(value=>value.id===item.nodeId);return node&& !['127.0.0.1','::1','localhost'].includes(node.listenHost)}))

function blank(type:NodeType):NodeInput { if(type==='snell')return{type,name:'新 Snell 节点',runtimeVersion:'v5.0.1',listenHost:'0.0.0.0',listenPort:6160,config:{version:'v5',tfo:true}};if(type==='ss2022')return{type,name:'新 SS-2022 节点',runtimeVersion:'v1.24.0',listenHost:'0.0.0.0',listenPort:20000,config:{mode:'tcp_and_udp',method:'2022-blake3-aes-128-gcm',tfo:true}};if(type==='anyconnect')return{type,name:'新 AnyConnect 节点',runtimeVersion:'v1.5.0',listenHost:'0.0.0.0',listenPort:443,config:{udpEnabled:true,serverName:'',vpnNetwork:'192.168.144.0/24',dns:'1.1.1.1,8.8.8.8',chinaDirectDns:'223.5.5.5,119.29.29.29',mtu:1340,maxClients:32,maxSameClients:2,profileEnabled:true,profileEntries:'',certificateUrl:'',privateKeyUrl:'',certificateUsername:'',certificateSchedule:'daily',certificateScheduleDay:0,certificateScheduleTime:'03:30',chinaCidrSourceUrl:'https://ftp.apnic.net/stats/apnic/delegated-apnic-latest',chinaCidrSourceFormat:'apnic',chinaCidrSchedule:'daily',chinaCidrScheduleDay:0,chinaCidrScheduleTime:'04:10'}};return{type,name:'新 ShadowTLS 节点',runtimeVersion:'v0.2.25',listenHost:'0.0.0.0',listenPort:8443,backendNodeId:nodes.value.find(n=>n.type!=='shadowtls'&&n.type!=='anyconnect')?.id,config:{version:'v3',sni:'www.microsoft.com',wildcardSni:'off',tfo:true}} }
function statusLabel(value:string){return({running:'运行中',stopped:'已停止',failed:'失败',degraded:'降级',starting:'启动中',stopping:'停止中',updating:'更新中'} as Record<string,string>)[value]??value}
function typeLabel(value:NodeType){return value==='snell'?'Snell':value==='ss2022'?'SS-2022':value==='anyconnect'?'AnyConnect':'ShadowTLS'}
function bytes(value:number){if(!value)return '0 B';const units=['B','KiB','MiB','GiB','TiB'];const i=Math.min(Math.floor(Math.log(value)/Math.log(1024)),4);return `${(value/1024**i).toFixed(i?1:0)} ${units[i]}`}
function flash(message:string,isError=false){(isError?error:notice).value=message;setTimeout(()=>{error.value='';notice.value=''},4500)}
function toggleTheme(){theme.value=nextTheme(theme.value);applyTheme(theme.value)}
async function initial(){try{const state=await api<{mustChangePassword:boolean}>('/auth/session');phase.value=state.mustChangePassword?'change':'app';if(phase.value==='app')await refresh()}catch{phase.value='login'}}
async function login(){busy.value=true;error.value='';try{const result=await api<{mustChangePassword:boolean}>('/auth/login',{method:'POST',body:JSON.stringify({password:password.value})});password.value='';phase.value=result.mustChangePassword?'change':'app';if(phase.value==='app')await refresh()}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function change(){if(newPassword.value!==confirmPassword.value){flash('两次输入的密码不一致',true);return}busy.value=true;try{await api('/auth/change-password',{method:'POST',body:JSON.stringify({newPassword:newPassword.value})});newPassword.value='';confirmPassword.value='';phase.value='login';flash('密码已修改，全部旧会话已注销，请重新登录')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function logout(){try{await api('/auth/logout',{method:'POST'})}finally{phase.value='login';nodes.value=[]}}
async function refresh(){const [dash,t,p,b,a,s]=await Promise.all([api<any>('/dashboard'),api<Traffic[]>('/traffic'),api<ProjectTraffic>('/traffic/project'),api<Backup[]>('/backups'),api<Audit[]>('/audit'),api<SystemSettings>('/settings')]);nodes.value=dash.nodes??[];traffic.value=t??[];projectTraffic.value=p;backups.value=b??[];audits.value=a??[];systemSettings.value=s;logMaxMB.value=s.logMaxMB;logEnabled.value=s.logEnabled;if(!logNodeId.value)logNodeId.value=nodes.value[0]?.id??'';await loadAnyConnectUsers();try{update.value=await api<UpdateStatus>('/updates/status')}catch{update.value=null}}
function openCreate(type:NodeType){editing.value=null;form.value=blank(type);showEditor.value=true}
function openEdit(node:Node){editing.value=node;form.value={name:node.name,runtimeVersion:node.runtimeVersion,listenHost:node.listenHost,listenPort:node.listenPort,backendNodeId:node.backendNodeId,config:{...node.config}};showEditor.value=true}
async function saveNode(){busy.value=true;try{let runtimeMessage='';if(editing.value){await api(`/nodes/${editing.value.id}`,{method:'PUT',body:JSON.stringify(form.value)})}else{const result=await api<{runtimeMessage?:string}>('/nodes',{method:'POST',body:JSON.stringify(form.value)});runtimeMessage=result.runtimeMessage??''};showEditor.value=false;await refresh();flash(runtimeMessage?`节点已创建，但首次应用失败：${runtimeMessage}`:editing.value?'节点已更新':'节点已创建并完成首次应用',Boolean(runtimeMessage))}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function action(node:Node,act:'start'|'stop'|'restart'){busy.value=true;try{await api(`/nodes/${node.id}/${act}`,{method:'POST'});await refresh();flash(`${node.name}：${act==='start'?'已启动':act==='stop'?'已停止':'已重启'}`)}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function removeNode(node:Node){if(!confirm(`确定删除“${node.name}”？依赖关系会先校验。`))return;try{await api(`/nodes/${node.id}`,{method:'DELETE'});await refresh();flash('节点已删除')}catch(e){flash(message(e),true)}}
async function logs(node:Node){page.value='audit';auditMode.value='runtime';logNodeId.value=node.id;await loadNodeLogs()}
async function loadNodeLogs(){if(!logNodeId.value)return;logBusy.value=true;try{const result=await api<NodeLogs>(`/nodes/${logNodeId.value}/logs?tail=${logTail.value}`);nodeLogs.value={...result,lines:result.lines??[]}}catch(e){flash(message(e),true)}finally{logBusy.value=false}}
function logClass(line:string){if(line.includes('异常')||line.includes('错误'))return 'log-error';if(line.includes('限额')||line.includes('暂停'))return 'log-warning';if(line.includes('运行状态'))return 'log-state';if(line.includes('流量活动'))return 'log-traffic';return ''}
async function configs(node:Node){try{const value=await api<ClientConfig>(`/nodes/${node.id}/client-configs`);detailTitle.value=`${node.name} · 客户端配置`;detailText.value='';detailConfig.value=value;detailNode.value=node;copiedKey.value='';showDetails.value=true}catch(e){flash(message(e),true)}}
function anyConnectProfileURL(node:Node|null){return node?`/api/v1/nodes/${encodeURIComponent(node.id)}/anyconnect/profile.xml`:''}
async function loadAnyConnectUsers(){const acNodes=nodes.value.filter(node=>node.type==='anyconnect');if(!acNodes.length){anyConnectUsers.value=[];anyConnectUserTraffic.value={};return}try{const results=await Promise.all(acNodes.map(node=>api<Array<AnyConnectUser & {traffic?:AnyConnectUserTraffic}>>(`/nodes/${node.id}/anyconnect/users`)));const users=results.flat();anyConnectUsers.value=users.map(({traffic:_,...user})=>user);anyConnectUserTraffic.value=Object.fromEntries(users.map(user=>[user.id,user.traffic??{userId:user.id,period:'',uploadBytes:0,downloadBytes:0,quotaBytes:0,resetDay:1,paused:false,pausedByQuota:false,updatedAt:''}]));}catch(e){flash(message(e),true)}}
async function manageAnyConnect(node:Node){anyConnectNode.value=node;showAnyConnect.value=true;await loadAnyConnect()}
async function loadAnyConnect(){if(!anyConnectNode.value)return;try{const assets=await api<AnyConnectAssetState>(`/nodes/${anyConnectNode.value.id}/anyconnect/assets`);anyConnectAssets.value=assets;await loadAnyConnectUsers()}catch(e){flash(message(e),true)}}
function openAnyConnectUser(user?:AnyConnectUser,node?:Node){if(user)anyConnectNode.value=nodes.value.find(value=>value.id===user.nodeId)??anyConnectNode.value;else if(node)anyConnectNode.value=node;else if(!anyConnectNode.value)anyConnectNode.value=anyConnectNodes.value[0]??null;editingAnyConnectUser.value=user??null;anyConnectUserForm.value=user?{username:user.username,password:'',routeGroup:user.routeGroup,enabled:user.enabled}:{username:'',password:'',routeGroup:'cn',enabled:true};showAnyConnectUserEditor.value=true}
async function saveAnyConnectUser(){if(!anyConnectNode.value)return;busy.value=true;try{const path=editingAnyConnectUser.value?`/nodes/${anyConnectNode.value.id}/anyconnect/users/${editingAnyConnectUser.value.id}`:`/nodes/${anyConnectNode.value.id}/anyconnect/users`;await api(path,{method:editingAnyConnectUser.value?'PUT':'POST',body:JSON.stringify(anyConnectUserForm.value)});showAnyConnectUserEditor.value=false;await loadAnyConnect();await refresh();flash(editingAnyConnectUser.value?'用户已更新并应用':'用户已创建并应用')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function removeAnyConnectUser(user:AnyConnectUser){if(!confirm(`删除 AnyConnect 用户“${user.username}”？`))return;busy.value=true;try{await api(`/nodes/${user.nodeId}/anyconnect/users/${user.id}`,{method:'DELETE'});await loadAnyConnect();await refresh();flash('用户已删除并应用')}catch(e){flash(message(e),true)}finally{busy.value=false}}
function openAnyConnectTraffic(user:AnyConnectUser){anyConnectTrafficEditing.value=user;const traffic=anyConnectUserTraffic.value[user.id];anyConnectTrafficQuotaGiB.value=Number(((traffic?.quotaBytes??0)/1024**3).toFixed(2));anyConnectTrafficResetDay.value=traffic?.resetDay??1;showAnyConnectTrafficEditor.value=true}
async function saveAnyConnectTraffic(){const user=anyConnectTrafficEditing.value;if(!user)return;busy.value=true;try{await api(`/nodes/${user.nodeId}/anyconnect/users/${user.id}/traffic/quota`,{method:'PUT',body:JSON.stringify({quotaBytes:Math.round(Math.max(0,anyConnectTrafficQuotaGiB.value)*1024**3),resetDay:anyConnectTrafficResetDay.value})});showAnyConnectTrafficEditor.value=false;await refresh();if(showAnyConnect.value)await loadAnyConnect();flash('用户流量限额已更新')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function resetAnyConnectTraffic(user:AnyConnectUser){if(!confirm(`清零用户“${user.username}”当前周期的流量？`))return;busy.value=true;try{await api(`/nodes/${user.nodeId}/anyconnect/users/${user.id}/traffic/reset`,{method:'POST'});await refresh();if(showAnyConnect.value)await loadAnyConnect();flash('用户流量已清零')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function refreshAnyConnectAsset(kind:'certificate'|'cidr'){if(!anyConnectNode.value)return;busy.value=true;try{await api(`/nodes/${anyConnectNode.value.id}/anyconnect/assets/${kind}/refresh`,{method:'POST'});await loadAnyConnect();await refresh();flash(kind==='certificate'?'证书已校验并更新':'中国 CIDR 已校验并更新')}catch(e){await loadAnyConnect();flash(message(e),true)}finally{busy.value=false}}
function routeGroupLabel(group:string){return group==='full'?'全隧道':group==='cn'?'中国直连':'登录时选择'}
async function copyText(value:string|undefined,key:string){if(!value)return;const copied=await copyToClipboard(value);if(copied){copiedKey.value=key;setTimeout(()=>{if(copiedKey.value===key)copiedKey.value=''},1800)}else flash('自动复制失败，请长按配置文本手动复制',true)}
function openTraffic(item:Traffic){trafficEditing.value=item;trafficQuotaGiB.value=Number((item.quotaBytes/1024**3).toFixed(2));trafficResetDay.value=item.resetDay;showTrafficEditor.value=true}
async function saveTraffic(){if(!trafficEditing.value)return;busy.value=true;try{await api(`/traffic/${trafficEditing.value.nodeId}/quota`,{method:'PUT',body:JSON.stringify({quotaBytes:Math.round(Math.max(0,trafficQuotaGiB.value)*1024**3),resetDay:trafficResetDay.value})});showTrafficEditor.value=false;await refresh();flash('流量限额与重置周期已更新')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function toggleTraffic(item:Traffic){busy.value=true;try{await api(`/traffic/${item.nodeId}/${item.paused?'resume':'pause'}`,{method:'POST'});await refresh();flash(item.paused?'节点流量已恢复':'节点流量已暂停')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function resetTraffic(item:Traffic){if(!confirm('清零该节点当前周期的上传和下载流量？'))return;busy.value=true;try{await api(`/traffic/${item.nodeId}/reset`,{method:'POST'});await refresh();flash('节点流量已清零')}catch(e){flash(message(e),true)}finally{busy.value=false}}
function openProjectTraffic(){projectQuotaGiB.value=Number((projectTraffic.value.quotaBytes/1024**3).toFixed(2));projectResetDay.value=projectTraffic.value.resetDay;showProjectTrafficEditor.value=true}
async function saveProjectTraffic(){busy.value=true;try{await api('/traffic/project/quota',{method:'PUT',body:JSON.stringify({quotaBytes:Math.round(Math.max(0,projectQuotaGiB.value)*1024**3),resetDay:projectResetDay.value})});showProjectTrafficEditor.value=false;await refresh();flash('项目总流量限额与重置周期已更新')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function toggleProjectTraffic(){const wasPaused=projectTraffic.value.paused;busy.value=true;try{await api(`/traffic/project/${wasPaused?'resume':'pause'}`,{method:'POST'});await refresh();flash(wasPaused?'项目公网节点已恢复':'项目公网节点已暂停')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function resetProjectTraffic(){if(!confirm('清零整个项目当前周期的总流量，并解除项目级暂停？'))return;busy.value=true;try{await api('/traffic/project/reset',{method:'POST'});await refresh();flash('项目总流量已清零')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function checkUpdates(){busy.value=true;try{update.value=await api<UpdateStatus>('/updates/check',{method:'POST'});audits.value=await api<Audit[]>('/audit');flash('上游版本对比完成')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function applyUpdate(item:UpdateComponent){if(!confirm(`更新 ${item.name} 到 ${item.latestVersion}？系统会先自动创建备份，再更新并重启相关节点。`))return;busy.value=true;try{const result=await api<{status:UpdateStatus}>(`/updates/apply`,{method:'POST',body:JSON.stringify({component:item.key,version:item.latestVersion})});update.value=result.status;await refresh();flash(`${item.name} 已更新到 ${item.latestVersion}`)}catch(e){flash(message(e),true)}finally{busy.value=false}}
function uploadDefaultFormat(component:string){return component==='snell'?'zip':component==='shadowsocks-rust'?'tar.xz':'raw'}
function uploadComponentChanged(){uploadFormat.value=uploadDefaultFormat(uploadComponent.value);const item=update.value?.components.find(value=>value.key===uploadComponent.value);if(item&&item.latestVersion!=='检查失败')uploadVersion.value=item.latestVersion}
function prepareUpload(item:UpdateComponent){uploadComponent.value=item.key;uploadVersion.value=item.latestVersion==='检查失败'?'':item.latestVersion;uploadFormat.value=uploadDefaultFormat(item.key);document.getElementById('manual-runtime-upload')?.scrollIntoView({behavior:'smooth',block:'center'})}
function selectUploadFile(event:Event){uploadFile.value=(event.target as HTMLInputElement).files?.[0]??null}
async function uploadRuntime(){if(!uploadFile.value){flash('请选择运行时安装包',true);return}if(!uploadConfirmed.value){flash('请先确认文件来源与架构',true);return}const checksum=uploadSHA256.value.replace(/\s/g,'').toLowerCase();if(!/^[0-9a-f]{64}$/.test(checksum)){flash('SHA-256 必须是 64 位十六进制字符',true);return}const data=new FormData();data.append('component',uploadComponent.value);data.append('version',uploadVersion.value.trim());data.append('format',uploadFormat.value);data.append('sha256',checksum);data.append('file',uploadFile.value);busy.value=true;try{const result=await api<{status:UpdateStatus;nodesUpdated:number}>('/updates/upload',{method:'POST',body:data});update.value=result.status;uploadFile.value=null;uploadSHA256.value='';uploadConfirmed.value=false;if(uploadFileInput.value)uploadFileInput.value.value='';await refresh();flash(`上传适配完成，已更新 ${result.nodesUpdated} 个节点`)}catch(e){flash(message(e),true)}finally{busy.value=false}}
function selectSyncFile(event:Event){syncFile.value=(event.target as HTMLInputElement).files?.[0]??null}
async function exportSync(){busy.value=true;try{const response=await fetch('/api/v1/sync/export',{method:'POST',headers:{'X-CSRF-Token':decodeURIComponent(csrfToken())},credentials:'same-origin'});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.error?.message??'导出失败')}const blob=await response.blob();const disposition=response.headers.get('Content-Disposition')??'';const filename=disposition.match(/filename="([^"]+)"/)?.[1]??'proxy-panel-anyconnect-sync.json';const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;link.click();URL.revokeObjectURL(link.href);flash('AnyConnect 节点及用户配置已导出，请妥善保管 JSON 文件')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function importSync(){if(!syncFile.value){flash('请选择同步 JSON 文件',true);return}if(!confirm('导入会更新同 ID 或同类型同名 AnyConnect 节点，并同步用户及其流量限额；不会处理其他协议节点，也不会删除节点。确定继续？'))return;const data=new FormData();data.append('file',syncFile.value);data.append('replaceUsers',String(syncReplaceUsers.value));busy.value=true;try{const result=await api<{nodesCreated:number;nodesUpdated:number;usersCreated:number;usersUpdated:number;userQuotasUpdated:number;preBackupId:string}>('/sync/import',{method:'POST',body:data});syncFile.value=null;if(syncFileInput.value)syncFileInput.value.value='';await refresh();showSync.value=false;flash(`AnyConnect 导入完成：节点新建 ${result.nodesCreated}、更新 ${result.nodesUpdated}；用户新建 ${result.usersCreated}、更新 ${result.usersUpdated}；限额同步 ${result.userQuotasUpdated??0} 个。备份 ${result.preBackupId}`)}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function createBackup(){busy.value=true;try{await api('/backups',{method:'POST'});await refresh();flash('一致性备份已创建')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function deleteBackup(item:Backup){if(!confirm(`删除备份 ${item.filename}？`))return;await api(`/backups/${item.id}`,{method:'DELETE'});await refresh()}
async function restoreBackup(item:Backup){if(!confirm(`恢复 ${item.filename}？当前状态会先自动备份，协议进程会短暂停止，全部会话将注销。`))return;busy.value=true;try{await api(`/backups/${item.id}/restore`,{method:'POST'});phase.value='login';flash('恢复完成，请使用恢复后的密码重新登录')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function saveLogSettings(){busy.value=true;try{const result=await api<{settings:SystemSettings;cleanupPending:boolean}>('/settings/logs',{method:'PUT',body:JSON.stringify({logMaxMB:logMaxMB.value,logEnabled:logEnabled.value})});systemSettings.value=result.settings;logMaxMB.value=result.settings.logMaxMB;logEnabled.value=result.settings.logEnabled;flash(result.cleanupPending?'日志设置已保存，运行代理恢复后将自动清理':'日志设置已保存并立即执行清理')}catch(e){flash(message(e),true)}finally{busy.value=false}}
async function setPage(value:Page){page.value=value;await refresh().catch(e=>flash(message(e),true));if(value==='audit'&&auditMode.value==='runtime')await loadNodeLogs()}
function message(e:unknown){if(e instanceof APIError){if(e.code==='PASSWORD_CHANGE_REQUIRED')phase.value='change';if(e.status===401)phase.value='login';return e.message}return e instanceof Error?e.message:'请求失败'}
onMounted(initial)
</script>

<template>
  <main v-if="phase==='loading'" class="center"><div class="spinner"></div><p>正在启动安全控制台…</p></main>
  <main v-else-if="phase==='login'" class="auth-shell">
    <button type="button" class="theme-toggle auth-theme-toggle" :aria-label="theme==='dark'?'切换到白天模式':'切换到黑夜模式'" @click="toggleTheme">{{theme==='dark'?'☀ 白天模式':'☾ 黑夜模式'}}</button>
    <section class="auth-card"><div class="brand-mark">P</div><p class="eyebrow">PROXY PANEL</p><h1>欢迎回来</h1><p class="muted">输入管理员密码以继续</p><form @submit.prevent="login"><label>管理员密码<input v-model="password" type="password" autocomplete="current-password" autofocus required></label><button class="primary wide" :disabled="busy">{{busy?'验证中…':'登录控制台'}} </button></form><p class="security-note">面板可通过服务器 IP 访问。首次登录后请立即修改默认密码，并仅向可信 IP 放行管理端口。</p></section>
  </main>
  <main v-else-if="phase==='change'" class="auth-shell">
    <button type="button" class="theme-toggle auth-theme-toggle" :aria-label="theme==='dark'?'切换到白天模式':'切换到黑夜模式'" @click="toggleTheme">{{theme==='dark'?'☀ 白天模式':'☾ 黑夜模式'}}</button>
    <section class="auth-card"><div class="brand-mark warning">!</div><p class="eyebrow">首次登录保护</p><h1>请先修改默认密码</h1><p class="muted">完成前，节点、日志和系统接口均不可访问。</p><form @submit.prevent="change"><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" required></label><label>确认新密码<input v-model="confirmPassword" type="password" autocomplete="new-password" required></label><p class="hint">4–128 个 Unicode 字符；不能继续使用 password。空格会作为密码内容保留。</p><button class="primary wide" :disabled="busy">修改并注销全部会话</button></form></section>
  </main>
  <div v-else class="app-shell">
    <aside><div class="logo"><span>P</span><div>Proxy Panel</div></div><nav><button v-for="item in nav" :key="item.id" :class="{active:page===item.id}" @click="setPage(item.id)"><i>{{item.icon}}</i>{{item.label}}</button></nav><div class="aside-footer"><button @click="logout">退出登录</button></div></aside>
    <section class="workspace"><header><div><p class="eyebrow">{{nav.find(n=>n.id===page)?.label}}</p><h2>{{page==='dashboard'?'运行概览':nav.find(n=>n.id===page)?.label}}</h2></div><div class="header-actions"><span class="clock">{{new Date().toLocaleDateString('zh-CN')}}</span><button type="button" class="ghost theme-toggle" :aria-label="theme==='dark'?'切换到白天模式':'切换到黑夜模式'" @click="toggleTheme">{{theme==='dark'?'☀ 白天模式':'☾ 黑夜模式'}}</button><button class="ghost" @click="refresh">刷新</button></div></header>
      <div v-if="notice" class="toast success">{{notice}}</div><div v-if="error" class="toast error">{{error}}</div>
      <div v-if="page==='dashboard'" class="content">
        <div class="stats dashboard-stats"><article><span>Snell</span><b>{{counts.snell}}</b><small>多版本实例</small></article><article><span>SS-2022</span><b>{{counts.ss2022}}</b><small>TCP / UDP</small></article><article><span>ShadowTLS</span><b>{{counts.shadowtls}}</b><small>v3 前端</small></article><article><span>AnyConnect</span><b>{{counts.anyconnect}}</b><small>ocserv 1.5.0</small></article><article><span>项目总流量</span><b>{{bytes(projectTraffic.uploadBytes+projectTraffic.downloadBytes)}}</b><small>上传 {{bytes(projectTraffic.uploadBytes)}} · 下载 {{bytes(projectTraffic.downloadBytes)}}</small></article></div>
        <section class="panel"><div class="panel-title"><div><h3>节点健康</h3><p>期望状态与实际进程状态</p></div><button class="primary" @click="page='nodes'">管理节点</button></div><div class="node-grid"><article v-for="node in nodes" :key="node.id" class="node-card"><div><span :class="['status-dot',node.actualState]"></span><small>{{typeLabel(node.type)}}</small></div><h4>{{node.name}}</h4><p>{{node.listenHost}}:{{node.listenPort}}</p><footer><span :class="['badge',node.actualState]">{{statusLabel(node.actualState)}}</span></footer></article></div></section>
      </div>
      <div v-else-if="page==='nodes'" class="content">
        <div class="node-toolbar">
          <div class="tabs"><button v-for="type in (['snell','ss2022','shadowtls','anyconnect'] as NodeType[])" :key="type" :class="{active:selectedType===type}" @click="selectedType=type">{{typeLabel(type)}} <span>{{counts[type]}}</span></button></div>
          <div class="node-toolbar-actions"><button v-if="selectedType==='anyconnect'" class="ghost sync-trigger" @click="showSync=true">⇄ 跨服务同步</button><button class="primary" @click="openCreate(selectedType)">＋ 新建节点</button></div>
        </div>
        <section v-if="selectedType!=='anyconnect'" class="panel table-panel"><table><thead><tr><th>节点</th><th>监听</th><th>版本 / 模式</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="node in filteredNodes" :key="node.id"><td><b>{{node.name}}</b><small>{{node.id}}</small></td><td><code>{{node.listenHost}}:{{node.listenPort}}</code></td><td>{{node.config.version||node.config.method||node.config.serverName||node.runtimeVersion}}</td><td><span :class="['badge',node.actualState]">{{statusLabel(node.actualState)}}</span><small v-if="node.lastError" class="danger">{{node.lastError}}</small></td><td class="actions"><button @click="openEdit(node)">编辑</button><button @click="action(node,node.desiredState==='running'?'stop':'start')">{{node.desiredState==='running'?'停止':'启动'}}</button><button @click="action(node,'restart')">重启</button><button @click="configs(node)">配置</button><button @click="logs(node)">日志</button><button class="danger-text" @click="removeNode(node)">删除</button></td></tr></tbody></table><div v-if="!filteredNodes.length" class="empty">暂无节点</div></section>
        <section v-else class="node-stack">
          <article v-for="node in filteredNodes" :key="node.id" class="panel node-service-card">
            <div class="node-service-head"><div class="node-service-identity"><div class="node-kind"><span :class="['status-dot',node.actualState]"></span><span>ANYCONNECT</span><span class="node-state-text">{{statusLabel(node.actualState)}}</span></div><h3>{{node.name}}</h3><small>{{node.id}}</small></div><div class="actions node-service-actions"><button @click="openEdit(node)">编辑</button><button @click="action(node,node.desiredState==='running'?'stop':'start')">{{node.desiredState==='running'?'停止':'启动'}}</button><button @click="action(node,'restart')">重启</button><button @click="manageAnyConnect(node)">证书与路由</button><a class="config-download node-profile-download" :href="anyConnectProfileURL(node)" download>配置文件</a><button @click="logs(node)">日志</button><button class="danger-text" @click="removeNode(node)">删除</button></div></div>
            <div class="node-service-meta"><span><small>监听地址</small><code>{{node.listenHost}}:{{node.listenPort}}</code></span><span><small>版本 / 域名</small><b>{{node.config.serverName||node.runtimeVersion}}</b></span><span><small>用户数</small><b>{{anyConnectUsersByNode[node.id]?.length||0}} 个</b></span></div>
            <div class="node-users"><div class="node-users-head"><div><p class="eyebrow">节点用户</p><h4>已开通账号</h4><p>该用户仅属于当前 AnyConnect 节点，流量与限额独立计算。</p></div><button class="primary" @click="openAnyConnectUser(undefined,node)">＋ 添加用户</button></div><div class="table-panel nested-user-table"><table><thead><tr><th>用户名</th><th>路由组</th><th>本周期使用</th><th>流量限额</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="entry in anyConnectUsersByNode[node.id]||[]" :key="entry.user.id"><td><b>{{entry.user.username}}</b><small>{{entry.user.enabled?'允许登录':'已停用'}}</small></td><td>{{routeGroupLabel(entry.user.routeGroup)}}</td><td><strong>{{bytes(entry.traffic.uploadBytes+entry.traffic.downloadBytes)}}</strong><small>↑ {{bytes(entry.traffic.uploadBytes)}} · ↓ {{bytes(entry.traffic.downloadBytes)}}</small></td><td><span :class="['quota-value',entry.traffic.quotaBytes && entry.traffic.uploadBytes+entry.traffic.downloadBytes>=entry.traffic.quotaBytes?'quota-danger':'']">{{entry.traffic.quotaBytes?bytes(entry.traffic.quotaBytes):'不限'}}</span><small v-if="entry.traffic.period">{{entry.traffic.period}} · 每月 {{entry.traffic.resetDay}} 日重置</small></td><td><span :class="['badge',entry.user.enabled&&!entry.traffic.paused?'running':'failed']">{{entry.traffic.paused?(entry.traffic.pausedByQuota?'超限暂停':'已暂停'):entry.user.enabled?'启用':'停用'}}</span></td><td class="actions"><button @click="openAnyConnectTraffic(entry.user)">设限额</button><button @click="openAnyConnectUser(entry.user)">编辑</button><button @click="resetAnyConnectTraffic(entry.user)">清零</button><button class="danger-text" @click="removeAnyConnectUser(entry.user)">删除</button></td></tr></tbody></table><div v-if="!(anyConnectUsersByNode[node.id]?.length)" class="empty">该节点还没有用户，点击右上角添加账号。</div></div></div>
          </article>
          <section v-if="!filteredNodes.length" class="panel empty">暂无 AnyConnect 节点，点击右上角新建节点。</section>
        </section>
      </div>
      <div v-else-if="page==='traffic'" class="content"><div class="callout"><b>统计边界</b><span>只统计公网端口的实际入站与出站字节；排除本机 ShadowTLS 转发，避免重复计量。</span></div><section class="panel project-traffic"><div><small>整个项目 · {{projectTraffic.period}} · 每月 {{projectTraffic.resetDay}} 日重置</small><h3>{{bytes(projectTraffic.uploadBytes+projectTraffic.downloadBytes)}} <span>/ {{projectTraffic.quotaBytes?bytes(projectTraffic.quotaBytes):'不限'}}</span></h3><p>上传 {{bytes(projectTraffic.uploadBytes)}} · 下载 {{bytes(projectTraffic.downloadBytes)}}</p></div><div class="project-traffic-actions"><span :class="['badge',projectTraffic.paused?'failed':'running']">{{projectTraffic.paused?(projectTraffic.pausedByQuota?'总额超限':'全局暂停'):'正常'}}</span><div class="actions"><button @click="openProjectTraffic">设置总限额</button><button @click="toggleProjectTraffic">{{projectTraffic.paused?'恢复项目':'暂停项目'}}</button><button @click="resetProjectTraffic">清零总流量</button></div></div></section><section class="panel table-panel"><table><thead><tr><th>节点</th><th>周期</th><th>上传</th><th>下载</th><th>限额</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in publicTraffic" :key="item.nodeId"><td><b>{{nodes.find(n=>n.id===item.nodeId)?.name||item.nodeId}}</b></td><td>{{item.period}} · 每月 {{item.resetDay}} 日重置</td><td>{{bytes(item.uploadBytes)}}</td><td>{{bytes(item.downloadBytes)}}</td><td>{{item.quotaBytes?bytes(item.quotaBytes):'不限'}}</td><td><span :class="['badge',item.paused?'failed':'running']">{{item.paused?(item.pausedByQuota?'超限暂停':'已暂停'):'正常'}}</span></td><td class="actions"><button @click="openTraffic(item)">设置</button><button @click="toggleTraffic(item)">{{item.paused?'恢复':'暂停'}}</button><button @click="resetTraffic(item)">清零</button></td></tr></tbody></table><div v-if="!publicTraffic.length" class="empty">暂无公网节点</div></section></div>
      <div v-else-if="page==='updates'" class="content">
        <section class="panel update-center">
          <div class="panel-title"><div><h3>运行时版本对比与一键更新</h3><p>仅保留 Snell Server、shadowsocks-rust 和 ShadowTLS，更新前自动备份</p></div><button class="primary" :disabled="busy" @click="checkUpdates">{{busy?'检查中…':'检查上游版本'}}</button></div>
          <div class="update-summary"><span>面板 {{update?.panelVersion||'dev'}}</span><span>服务器架构 {{update?.architecture||'—'}}</span><span>适配器 Schema {{update?.adapter?.schemaVersion||'—'}}</span><span>最近检查 {{update?.checkedAt?new Date(update.checkedAt).toLocaleString('zh-CN'):'尚未检查'}}</span></div>
          <p class="callout">{{update?.message||'更新元数据尚未初始化。'}}</p>
          <div class="component-list"><article v-for="item in update?.components||[]" :key="item.key" class="component-card"><div class="component-main"><small>运行时</small><h4>{{item.name}}</h4><a :href="item.sourceUrl" target="_blank" rel="noreferrer">查看上游来源</a></div><div class="version-compare"><span>当前<b>{{item.currentVersion}}</b></span><i>→</i><span>上游<b>{{item.latestVersion}}</b></span></div><div class="component-state"><span :class="['badge',item.updateAvailable?(item.canApply?'degraded':'failed'):'running']">{{item.updateAvailable?(item.canApply?'可更新':'待适配'):'已是最新'}}</span><small>{{item.message}}</small><button v-if="item.canApply" class="primary" :disabled="busy" @click="applyUpdate(item)">备份并更新</button><button v-else-if="item.updateAvailable" class="upload-link" :disabled="busy" @click="prepareUpload(item)">上传适配</button></div></article></div>
        </section>
        <section id="manual-runtime-upload" class="panel manual-upload">
          <div class="panel-title"><div><h3>手动上传运行时</h3><p>从上游下载当前服务器架构的安装包，校验后安装并更新同类节点</p></div><span class="architecture-chip">{{update?.architecture||'—'}}</span></div>
          <form @submit.prevent="uploadRuntime">
            <div class="upload-grid">
              <label>运行时<select v-model="uploadComponent" @change="uploadComponentChanged"><option value="snell">Snell Server</option><option value="shadowsocks-rust">shadowsocks-rust</option><option value="shadowtls">ShadowTLS</option></select></label>
              <label>版本号<input v-model="uploadVersion" placeholder="例如 v1.25.0" maxlength="64" required></label>
              <label>安装包格式<select v-model="uploadFormat"><option value="zip">ZIP（Snell）</option><option value="tar.xz">tar.xz（shadowsocks-rust）</option><option value="raw">原始二进制（ShadowTLS）</option></select></label>
              <label>官方 SHA-256<input v-model="uploadSHA256" placeholder="64 位十六进制校验值" autocomplete="off" spellcheck="false" maxlength="80" required></label>
              <label class="upload-file">运行时安装包<input ref="uploadFileInput" type="file" required @change="selectUploadFile"><small>{{uploadFile?`${uploadFile.name} · ${bytes(uploadFile.size)}`:'最大 100 MiB；仅接受当前 Linux 架构的官方发布文件'}}</small></label>
            </div>
            <label class="check upload-confirm"><input v-model="uploadConfirmed" type="checkbox">我确认文件来自上方官方来源，SHA-256 与官方公布值一致，并与服务器 {{update?.architecture||'当前'}} 架构匹配。</label>
            <div class="upload-footer"><p>上传内容会再次检查哈希、归档结构、二进制名称和 ELF 架构；安装前自动创建配置备份，失败时回滚节点版本。</p><button class="primary" :disabled="busy">{{busy?'正在校验并安装…':'上传、校验并适配'}}</button></div>
          </form>
        </section>
        <section class="panel backup-panel"><div class="panel-title"><div><h3>配置备份</h3><p>SQLite 一致性快照、配置与主密钥；一键更新也会自动创建</p></div><button class="primary" :disabled="busy" @click="createBackup">创建备份</button></div><div class="backup" v-for="item in backups" :key="item.id"><div><b>{{item.filename}}</b><small>{{bytes(item.size)}} · {{new Date(item.createdAt).toLocaleString('zh-CN')}}</small></div><div class="actions"><button @click="restoreBackup(item)">恢复</button><button class="danger-text" @click="deleteBackup(item)">删除</button></div></div><div v-if="!backups.length" class="empty">还没有备份</div></section>

      </div>
      <div v-else-if="page==='audit'" class="content"><div class="tabs audit-tabs"><button :class="{active:auditMode==='runtime'}" @click="auditMode='runtime';loadNodeLogs()">节点运行日志</button><button :class="{active:auditMode==='audit'}" @click="auditMode='audit'">管理审计</button></div><section v-if="auditMode==='runtime'" class="log-layout"><aside class="panel log-node-list"><div class="panel-title"><div><h3>节点</h3><p>选择一个节点查看日志</p></div></div><button v-for="node in nodes" :key="node.id" :class="{active:logNodeId===node.id}" @click="logNodeId=node.id;loadNodeLogs()"><span :class="['status-dot',node.actualState]"></span><span><b>{{node.name}}</b><small>{{typeLabel(node.type)}} · {{node.listenHost}}:{{node.listenPort}}</small></span></button><div v-if="!nodes.length" class="empty">暂无节点</div></aside><section class="panel log-viewer"><div class="panel-title"><div><h3>{{nodes.find(n=>n.id===logNodeId)?.name||'节点日志'}}</h3><p>{{nodeLogs.updatedAt?`最后写入 ${new Date(nodeLogs.updatedAt).toLocaleString('zh-CN')} · ${bytes(nodeLogs.totalBytes)}`:'暂无日志'}}</p></div><div class="log-tools"><select v-model.number="logTail" @change="loadNodeLogs"><option :value="100">最近 100 行</option><option :value="300">最近 300 行</option><option :value="1000">最近 1000 行</option></select><button class="ghost" :disabled="logBusy||!logNodeId" @click="loadNodeLogs">{{logBusy?'读取中…':'刷新'}}</button></div></div><div class="log-console"><div v-for="(line,index) in nodeLogs.lines" :key="index" :class="['log-line',logClass(line)]"><span>{{String(index+1).padStart(3,'0')}}</span><code>{{line}}</code></div><div v-if="!nodeLogs.lines.length" class="empty">该节点暂无运行日志</div></div></section></section><section v-else class="panel table-panel"><table><thead><tr><th>时间</th><th>具体操作</th><th>目标</th><th>来源</th><th>结果</th></tr></thead><tbody><tr v-for="item in audits" :key="item.id"><td>{{new Date(item.createdAt).toLocaleString('zh-CN')}}</td><td><b>{{item.description}}</b><small>{{item.detailDescription||item.action}}</small></td><td>{{item.targetDescription}}<small>{{item.targetId||'—'}}</small></td><td>{{item.remoteIp}}</td><td><span :class="['badge',item.success?'running':'failed']">{{item.success?'成功':'失败'}}</span></td></tr></tbody></table></section></div>
      <div v-else class="content two-col"><section class="panel"><h3>安全设置</h3><p class="muted">修改密码会立即注销包括当前会话在内的全部 Session。</p><button class="primary" @click="phase='change'">修改管理员密码</button></section><section class="panel"><h3>日志存储</h3><p class="muted">所有节点日志共用一个空间上限，超限时会优先删除最旧的日志文件。运行代理每 3 分钟自动检查。</p><form class="setting-form" @submit.prevent="saveLogSettings"><label class="check"><input v-model="logEnabled" type="checkbox">记录节点运行日志</label><small class="field-hint">关闭后仍会读取进程输出，但不再写入节点日志文件；管理审计日志不受影响。</small><label>日志总上限（MB）<input v-model.number="logMaxMB" type="number" min="1" max="1024" required></label><button class="primary" :disabled="busy">保存并清理</button></form></section></div>
    </section>
  </div>
  <div v-if="showEditor" class="modal" @click.self="showEditor=false"><form class="dialog node-dialog" @submit.prevent="saveNode"><div class="panel-title"><div><p class="eyebrow">{{editing?'编辑':'创建'}} {{typeLabel((editing?.type||form.type) as NodeType)}}</p><h3>{{form.name}}</h3></div><button type="button" class="close" @click="showEditor=false">×</button></div><div class="form-grid"><label>名称<input v-model="form.name" required></label><label>监听地址<input v-model="form.listenHost" required><small class="field-hint">0.0.0.0 对外提供服务；127.0.0.1 仅本机可访问，适合 ShadowTLS 后端。</small></label><label>监听端口<input v-model.number="form.listenPort" type="number" min="1" max="65535" required></label><template v-if="(editing?.type||form.type)==='snell'"><label>协议版本<select v-model="form.config.version"><option>v4</option><option>v5</option><option>v6</option></select></label></template><template v-if="(editing?.type||form.type)==='ss2022'"><label>加密方法<select v-model="form.config.method"><option>2022-blake3-aes-128-gcm</option><option>2022-blake3-aes-256-gcm</option><option>2022-blake3-chacha20-poly1305</option></select></label><label>模式<select v-model="form.config.mode"><option value="tcp_and_udp">TCP + UDP</option><option value="tcp_only">仅 TCP</option><option value="udp_only">仅 UDP</option></select></label></template><template v-if="(editing?.type||form.type)==='shadowtls'"><label>后端节点<select v-model="form.backendNodeId"><option v-for="node in nodes.filter(n=>n.type!=='shadowtls'&&n.type!=='anyconnect')" :key="node.id" :value="node.id">{{node.name}}</option></select></label><label>SNI<input v-model="form.config.sni" required></label><label>wildcard-sni<select v-model="form.config.wildcardSni"><option value="off">关闭</option><option value="authed">已认证</option><option value="all">全部（高风险）</option></select></label></template><template v-if="(editing?.type||form.type)==='anyconnect'"><h4 class="form-section-title">服务与容量</h4><label>客户端连接域名<input v-model="form.config.serverName" placeholder="vpn.example.com" required></label><label>VPN IPv4 地址池<input v-model="form.config.vpnNetwork" required></label><label>全隧道 DNS（逗号分隔）<input v-model="form.config.dns" required></label><small class="field-hint">中国直连组仅将中国大陆 IPv4 直连，DNS 始终通过 VPN 节点解析。</small><label>MTU<input v-model.number="form.config.mtu" type="number" min="1200" max="1500" required></label><label>最大客户端数<input v-model.number="form.config.maxClients" type="number" min="1" max="4096" required></label><label>单用户同时连接数<input v-model.number="form.config.maxSameClients" type="number" min="1" max="64" required></label><label class="check"><input v-model="form.config.udpEnabled" type="checkbox">启用 UDP / DTLS（与 TCP 同端口）</label><h4 class="form-section-title">客户端节点列表（profile.xml）</h4><label class="check"><input v-model="form.config.profileEnabled" type="checkbox">下发可选服务器列表</label><label v-if="form.config.profileEnabled">节点列表（每行：显示名称 | 域名:端口）<textarea v-model="form.config.profileEntries" rows="5" placeholder="日本东京 | jp.example.com:443&#10;美国西海岸 | us.example.com:443"></textarea><small class="field-hint">列表第一项就是客户端默认节点；当前节点不在列表时会自动追加到末尾。建议把固定主节点放在第一行。</small></label><h4 class="form-section-title">证书分发中心</h4><label>证书下载地址<input v-model="form.config.certificateUrl" type="url" placeholder="https://…/server.crt.pem" required></label><label>私钥下载地址<input v-model="form.config.privateKeyUrl" type="url" placeholder="https://…/server.key.pem" required></label><label>Basic Auth 用户名（可留空）<input v-model="form.config.certificateUsername" autocomplete="off"></label><label>下载密码（编辑时留空保持）<input v-model="form.certificatePassword" type="password" autocomplete="new-password"></label><label>私钥口令（留空时同下载密码）<input v-model="form.privateKeyPassphrase" type="password" autocomplete="new-password"></label><label>证书更新频率<select v-model="form.config.certificateSchedule"><option value="daily">每天</option><option value="weekly">每周</option><option value="manual">仅手动</option></select></label><label v-if="form.config.certificateSchedule==='weekly'">证书更新星期<select v-model.number="form.config.certificateScheduleDay"><option :value="0">周日</option><option :value="1">周一</option><option :value="2">周二</option><option :value="3">周三</option><option :value="4">周四</option><option :value="5">周五</option><option :value="6">周六</option></select></label><label v-if="form.config.certificateSchedule!=='manual'">证书更新时间<input v-model="form.config.certificateScheduleTime" type="time" required></label><h4 class="form-section-title">中国直连 CIDR</h4><label>CIDR 数据源<input v-model="form.config.chinaCidrSourceUrl" type="url" required></label><label>数据格式<select v-model="form.config.chinaCidrSourceFormat"><option value="apnic">APNIC delegated</option><option value="cidr">CIDR / ocserv no-route 列表</option></select></label><label>路由更新频率<select v-model="form.config.chinaCidrSchedule"><option value="daily">每天</option><option value="weekly">每周</option><option value="manual">仅手动</option></select></label><label v-if="form.config.chinaCidrSchedule==='weekly'">路由更新星期<select v-model.number="form.config.chinaCidrScheduleDay"><option :value="0">周日</option><option :value="1">周一</option><option :value="2">周二</option><option :value="3">周三</option><option :value="4">周四</option><option :value="5">周五</option><option :value="6">周六</option></select></label><label v-if="form.config.chinaCidrSchedule!=='manual'">路由更新时间<input v-model="form.config.chinaCidrScheduleTime" type="time" required></label></template><template v-if="(editing?.type||form.type)!=='anyconnect'"><label class="check"><input v-model="form.config.tfo" type="checkbox">启用 TCP Fast Open</label><label>密钥 / 密码（留空自动生成或保持原值）<input v-model="form.secret" type="password" autocomplete="new-password"></label></template></div><p v-if="(editing?.type||form.type)==='anyconnect'" class="hint">定时任务使用容器 TZ。证书和私钥仅在全部校验通过后原子切换；面板不会自动修改宿主机 IPv4 转发设置。</p><footer class="dialog-actions"><button type="button" @click="showEditor=false">取消</button><button class="primary" :disabled="busy">{{busy?'应用中…':'验证并应用'}}</button></footer></form></div>
  <div v-if="showTrafficEditor" class="modal" @click.self="showTrafficEditor=false"><form class="dialog traffic-dialog" @submit.prevent="saveTraffic"><div class="panel-title"><div><p class="eyebrow">流量管理</p><h3>{{nodes.find(n=>n.id===trafficEditing?.nodeId)?.name}}</h3></div><button type="button" class="close" @click="showTrafficEditor=false">×</button></div><div class="form-grid"><label>月流量限额（GiB，0 = 不限）<input v-model.number="trafficQuotaGiB" type="number" min="0" step="0.1" required></label><label>每月重置日<input v-model.number="trafficResetDay" type="number" min="1" max="28" required></label></div><p class="hint">流量达到限额后会自动暂停公网端口，到下一计费周期自动恢复。</p><footer class="dialog-actions"><button type="button" @click="showTrafficEditor=false">取消</button><button class="primary" :disabled="busy">保存设置</button></footer></form></div>
  <div v-if="showProjectTrafficEditor" class="modal" @click.self="showProjectTrafficEditor=false"><form class="dialog traffic-dialog" @submit.prevent="saveProjectTraffic"><div class="panel-title"><div><p class="eyebrow">项目总流量</p><h3>全部公网节点</h3></div><button type="button" class="close" @click="showProjectTrafficEditor=false">×</button></div><div class="form-grid"><label>月总流量限额（GiB，0 = 不限）<input v-model.number="projectQuotaGiB" type="number" min="0" step="0.1" required></label><label>每月重置日<input v-model.number="projectResetDay" type="number" min="1" max="28" required></label></div><p class="hint">总流量达到限额后会暂停全部公网节点；新周期只恢复未被单独暂停的节点。</p><footer class="dialog-actions"><button type="button" @click="showProjectTrafficEditor=false">取消</button><button class="primary" :disabled="busy">保存设置</button></footer></form></div>
  <div v-if="showAnyConnect" class="modal" @click.self="showAnyConnect=false"><section class="dialog anyconnect-dialog"><div class="panel-title"><div><p class="eyebrow">AnyConnect 资源</p><h3>{{anyConnectNode?.name}}</h3><p>证书与中国大陆路由数据</p></div><button class="close" @click="showAnyConnect=false">×</button></div><div class="asset-grid"><article><div><b>服务器证书</b><span :class="['badge',anyConnectAssets?.certificateError?'failed':'running']">{{anyConnectAssets?.certificateError?'更新失败':anyConnectAssets?.certificateLastSuccess?'已验证':'待拉取'}}</span></div><small v-if="anyConnectAssets?.certificateLastSuccess">更新于 {{new Date(anyConnectAssets.certificateLastSuccess).toLocaleString('zh-CN')}} · 到期 {{new Date(anyConnectAssets.certificateNotAfter).toLocaleDateString('zh-CN')}}</small><small v-if="anyConnectAssets?.certificateError" class="danger">{{anyConnectAssets.certificateError}}</small><button :disabled="busy" @click="refreshAnyConnectAsset('certificate')">立即拉取并校验</button></article><article><div><b>中国大陆 CIDR</b><span :class="['badge',anyConnectAssets?.cidrError?'failed':'running']">{{anyConnectAssets?.cidrError?'更新失败':anyConnectAssets?.cidrLastSuccess?`${anyConnectAssets.cidrCount} 条`:'待拉取'}}</span></div><small v-if="anyConnectAssets?.cidrLastSuccess">更新于 {{new Date(anyConnectAssets.cidrLastSuccess).toLocaleString('zh-CN')}}</small><small v-if="anyConnectAssets?.cidrError" class="danger">{{anyConnectAssets.cidrError}}</small><button :disabled="busy" @click="refreshAnyConnectAsset('cidr')">立即更新路由</button></article></div><p class="hint asset-note">用户账号、使用流量和单独限额已归入 AnyConnect 节点卡片中管理。</p></section></div>
  <div v-if="showSync" class="modal" @click.self="showSync=false"><section class="dialog sync-dialog"><div class="panel-title"><div><p class="eyebrow">跨服务同步</p><h3>AnyConnect 节点与用户</h3><p>在不同服务器之间导出或导入节点和用户配置。</p></div><button class="close" @click="showSync=false">×</button></div><div class="sync-dialog-body"><button class="sync-export-card" :disabled="busy" @click="exportSync"><span>⇩</span><strong>导出 JSON</strong><small>导出当前 AnyConnect 节点、用户、限额与证书凭据</small></button><form class="sync-import-form" @submit.prevent="importSync"><label>导入 JSON 文件<input ref="syncFileInput" type="file" accept="application/json,.json" required @change="selectSyncFile"><small>{{syncFile ? syncFile.name + ' · ' + bytes(syncFile.size) : '选择其他服务器导出的文件'}}</small></label><label class="check"><input v-model="syncReplaceUsers" type="checkbox">移除目标节点中未包含的用户</label><button class="primary" :disabled="busy">导入并合并</button></form></div><p class="sync-security-note">导入前自动创建备份。文件包含证书凭据与用户密码，请仅在安全链路传输。</p></section></div>
  <div v-if="showAnyConnectUserEditor" class="modal modal-nested" @click.self="showAnyConnectUserEditor=false"><form class="dialog user-dialog" @submit.prevent="saveAnyConnectUser"><div class="panel-title"><div><p class="eyebrow">{{editingAnyConnectUser?'编辑':'添加'}} AnyConnect 用户</p><h3>{{anyConnectUserForm.username||'新用户'}}</h3></div><button type="button" class="close" @click="showAnyConnectUserEditor=false">×</button></div><div class="form-grid"><label>用户名<input v-model="anyConnectUserForm.username" autocomplete="off" maxlength="64" required></label><label>{{editingAnyConnectUser?'新密码（留空保持）':'密码'}}<input v-model="anyConnectUserForm.password" type="password" autocomplete="new-password" :required="!editingAnyConnectUser"></label><label>路由组<select v-model="anyConnectUserForm.routeGroup"><option value="full">全隧道</option><option value="cn">中国直连</option><option value="select">登录时选择</option></select><small class="field-hint">中国直连：大陆 IPv4 不进 VPN，其余流量走隧道。</small></label><label class="check"><input v-model="anyConnectUserForm.enabled" type="checkbox">允许此用户登录</label></div><footer class="dialog-actions"><button type="button" @click="showAnyConnectUserEditor=false">取消</button><button class="primary" :disabled="busy">保存并应用</button></footer></form></div>
  <div v-if="showAnyConnectTrafficEditor" class="modal modal-nested" @click.self="showAnyConnectTrafficEditor=false"><form class="dialog traffic-dialog" @submit.prevent="saveAnyConnectTraffic"><div class="panel-title"><div><p class="eyebrow">用户流量</p><h3>{{anyConnectTrafficEditing?.username}}</h3><p>仅影响这个 AnyConnect 账号</p></div><button type="button" class="close" @click="showAnyConnectTrafficEditor=false">×</button></div><div class="form-grid"><label>月流量限额（GiB，0 = 不限）<input v-model.number="anyConnectTrafficQuotaGiB" type="number" min="0" step="0.1" required></label><label>每月重置日<input v-model.number="anyConnectTrafficResetDay" type="number" min="1" max="28" required></label></div><p class="hint">达到限额后仅暂停该用户的 VPN 流量，不影响同节点其他用户。</p><footer class="dialog-actions"><button type="button" @click="showAnyConnectTrafficEditor=false">取消</button><button class="primary" :disabled="busy">保存限额</button></footer></form></div>
 <div v-if="showDetails" class="modal" @click.self="showDetails=false"><section class="dialog details"><div class="panel-title"><div><h3>{{detailTitle}}</h3><p v-if="detailConfig">{{detailConfig.protocolLabel}}</p></div><button class="close" @click="showDetails=false">×</button></div><template v-if="detailConfig"><div v-if="detailNode?.type==='shadowtls'" class="callout config-explain"><b>这是组合配置，不是协议错配</b><span>客户端先连接 ShadowTLS 公网端口，再由服务器转发到 {{detailConfig.protocolLabel.includes('Snell')?'Snell':'SS-2022'}} 后端；因此配置中会同时出现两种协议参数。</span></div><div :class="['config-layout',{'no-qr':!detailConfig.qrCode}]"><div class="config-sections"><section v-if="detailNode?.type==='anyconnect'" class="config-block profile-download-block"><div><b>AnyConnect 配置文件（profile.xml）</b><a class="config-download" :href="anyConnectProfileURL(detailNode)" download>下载配置文件</a></div><p class="config-note">在 Cisco Secure Client 的“配置文件”页面选择“导入配置文件”，然后选中下载的 XML。</p></section><section v-if="detailConfig.primary" class="config-block"><div><b>{{detailConfig.primaryLabel}}</b><button :class="{copied:copiedKey==='primary'}" @click="copyText(detailConfig.primary,'primary')">{{copiedKey==='primary'?'✓':'复制'}}</button></div><pre>{{detailConfig.primary}}</pre></section><p v-if="detailConfig.importNote" class="callout import-note">{{detailConfig.importNote}}</p><section v-if="detailConfig.openConnect" class="config-block"><div><b>{{detailConfig.openConnectLabel}}</b><button :class="{copied:copiedKey==='openconnect'}" @click="copyText(detailConfig.openConnect,'openconnect')">{{copiedKey==='openconnect'?'✓':'复制'}}</button></div><pre>{{detailConfig.openConnect}}</pre></section><section v-if="detailConfig.surge" class="config-block"><div><b>{{detailConfig.surgeLabel||'Surge [Proxy] 节点行'}}</b><button v-if="!detailConfig.surge.startsWith('#')" :class="{copied:copiedKey==='surge'}" @click="copyText(detailConfig.surge,'surge')">{{copiedKey==='surge'?'✓':'复制'}}</button></div><pre>{{detailConfig.surge}}</pre></section><section v-if="detailConfig.surgeAlternative" class="config-block"><div><b>{{detailConfig.surgeAlternativeLabel}}</b><button :class="{copied:copiedKey==='surge-alt'}" @click="copyText(detailConfig.surgeAlternative,'surge-alt')">{{copiedKey==='surge-alt'?'✓':'复制'}}</button></div><pre>{{detailConfig.surgeAlternative}}</pre></section><p v-if="detailConfig.surgeNote" class="config-note">{{detailConfig.surgeNote}}</p><section class="config-block"><div><b>{{detailNode?.type==='anyconnect'?'Clash / Mihomo 说明':'Clash / Mihomo 配置'}}</b><button v-if="!detailConfig.clash.startsWith('#')" :class="{copied:copiedKey==='clash'}" @click="copyText(detailConfig.clash,'clash')">{{copiedKey==='clash'?'✓':'复制'}}</button></div><pre>{{detailConfig.clash}}</pre></section><section v-if="detailConfig.clashInline" class="config-block"><div><b>Clash / Mihomo 单行配置</b><button :class="{copied:copiedKey==='clash-inline'}" @click="copyText(detailConfig.clashInline,'clash-inline')">{{copiedKey==='clash-inline'?'✓':'复制'}}</button></div><pre>{{detailConfig.clashInline}}</pre></section><p v-if="detailConfig.warning" class="callout warning-box">{{detailConfig.warning}}</p></div><aside v-if="detailConfig.qrCode" class="qr-card"><img :src="detailConfig.qrCode" alt="Shadowrocket 可导入的 SS 配置二维码"><b>Shadowrocket 扫码导入</b><small>{{detailConfig.qrCodeLabel}}</small></aside></div><p class="secret-note">{{detailNode?.type==='anyconnect'?'客户端凭据不会在此页面展示。':'配置包含完整密钥，仅在已登录的安全会话内展示。请勿截图或转发给无关人员。'}}</p></template><pre v-else>{{detailText}}</pre></section></div>
</template>
